#!/usr/bin/env python3
"""Builds podcast_script_kjt{,_fr,_de,_lb}.md from build/kjt_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the cnpd scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "kjt"
HEAD = {
 "en": ('# Podcast Script — "The Kanner-Jugendtelefon – 116 111, Someone Who Listens"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « Le Kanner-Jugendtelefon – 116 111, quelqu'un qui écoute »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Das Kanner-Jugendtelefon – 116 111, jemand hört zu“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „De Kanner-Jugendtelefon – 116 111, een deen nolauschtert“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 10, "fr": 9, "de": 10, "lb": 10}   # EN 9:58, FR 9:14, DE 10:26 (shortened 26 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources: kjt.lu (KJT – Kanner-Jugendtelefon, a service of CJF Lëtzebuerg a.s.b.l.), consulted on 24 November 2026 in German, English and French — home page, \"116 111\" (free, anonymous, confidential; opening hours), \"Online Help\" (username and password, languages), \"Chat counselling\" (trained young counsellors), \"Elterentelefon\" (8002 4444; parents, grandparents and adults responsible for children), \"BEE SECURE Helpline\" (8002 1234; every citizen of any age; only reachable from the Luxembourg network; contact form confidential but not anonymous), \"BEE SECURE Stopline\" (three categories of illegal content), \"Who we are\" (founded in 1992 in connection with the UN Convention on the Rights of the Child; four founding organisations; agreement with the SNJ; five counselling principles; 2007: Elterentelefon, BEE SECURE Helpline and Stopline; 2021: peer-to-peer chat; international networks; motto), \"Volunteer work at KJT\" (basic training, internship, shifts, supervision), \"Contact\" (no counselling through the contact form), topic pages and toolbox; stopline.bee-secure.lu (what can be reported, what happens with a report, no data stored that identifies the person reporting). Exact opening hours, the days with a service in English, the reply times of the Online Help, the hours of the volunteer training and the age limit of the chat counsellors are deliberately not given: they can change, and on 24 November 2026 the language versions of the website did not fully agree on some of them. The remark that adults can pass on the number and the reminder about the emergency number 112 are additions by the hosts, not taken from kjt.lu. General information only. Accurate as of November 2026.*",
 "fr": "*Sources : kjt.lu (KJT – Kanner-Jugendtelefon, un service de CJF Lëtzebuerg a.s.b.l.), consulté le 24 novembre 2026 en allemand, en anglais et en français — page d'accueil, « 116 111 » (gratuit, anonyme, confidentiel ; horaires), « Online Help » (nom d'utilisateur et mot de passe, langues), « Conseils par chat » (jeunes conseillers formés), « Elterentelefon (Ecoute Parents) » (8002 4444 ; parents, grands-parents et adultes responsables d'enfants), « BEE SECURE Helpline » (8002 1234 ; tout citoyen de tout âge ; joignable uniquement depuis le réseau luxembourgeois ; formulaire de contact confidentiel mais pas anonyme), « BEE SECURE Stopline » (trois catégories de contenus illégaux), « À propos de nous » (fondation en 1992 dans le cadre de la Convention des Nations Unies relative aux droits de l'enfant ; quatre organisations fondatrices ; convention avec le SNJ ; cinq principes ; 2007 : Elterentelefon, BEE SECURE Helpline et Stopline ; 2021 : chat de pair à pair ; réseaux internationaux ; devise), « Travail bénévole au KJT » (formation de base, stage, permanences, supervision), « Contact » (pas de conseil par le formulaire de contact), pages thématiques et boîte à outils ; stopline.bee-secure.lu (contenus à signaler, traitement d'un signalement, aucune donnée enregistrée permettant d'identifier la personne). Les horaires exacts, les jours avec un service en anglais, les délais de réponse de l'Online Help, le nombre d'heures de la formation des bénévoles et la limite d'âge des conseillers du chat ne sont volontairement pas donnés : ils peuvent changer et, le 24 novembre 2026, les versions linguistiques du site ne concordaient pas entièrement sur certains points. La remarque sur les adultes qui transmettent le numéro et le rappel du numéro d'urgence 112 sont des ajouts des animateurs, et ne viennent pas de kjt.lu. Informations générales uniquement. Exact en novembre 2026.*",
 "de": "*Quellen: kjt.lu (KJT – Kanner-Jugendtelefon, ein Service von CJF Lëtzebuerg a.s.b.l.), abgerufen am 24. November 2026 auf Deutsch, Englisch und Französisch — Startseite, „116 111“ (kostenlos, anonym, vertraulich; Zeiten), „Online Help“ (Benutzername und Passwort, Sprachen), „Chatberodung“ (ausgebildete junge Berater), „Elterentelefon“ (8002 4444; Eltern, Großeltern und alle, die mit Kindern oder Jugendlichen zu tun haben), „BEE SECURE Helpline“ (8002 1234; jeder Bürger jeden Alters; nur aus dem luxemburgischen Netz erreichbar; Kontaktformular vertraulich, aber nicht anonym), „BEE SECURE Stopline“ (drei Kategorien illegaler Inhalte), „Wer wir sind“ (Gründung 1992 im Rahmen der UN-Kinderrechtskonvention; vier Gründungsorganisationen; Konvention mit dem SNJ; fünf Beratungsprinzipien; 2007: Elterentelefon, BEE SECURE Helpline und Stopline; 2021: Peer-to-Peer-Chat; internationale Netzwerke; Motto), „Ehrenamtliche Mitarbeit am KJT“ (Grundausbildung, Praktikum, Dienste, Supervision), „Kontakt“ (keine Beratung über das Kontaktformular), Themenseiten und Toolbox; stopline.bee-secure.lu (was gemeldet werden kann, was mit einer Meldung geschieht, keine Speicherung von Daten, die die meldende Person erkennbar machen). Genaue Zeiten, die Tage mit einem Angebot auf Englisch, die Antwortfristen der Online Help, die Stundenzahl der Ausbildung der Ehrenamtlichen und die Altersgrenze der Chatberater werden bewusst nicht genannt: Sie können sich ändern, und am 24. November 2026 stimmten die Sprachversionen der Website in einigen Punkten nicht ganz überein. Der Hinweis, dass Erwachsene die Nummer weitergeben können und die Erinnerung an die Notrufnummer 112 sind Ergänzungen der Moderatoren und stammen nicht von kjt.lu. Nur allgemeine Informationen. Stand: November 2026.*",
 "lb": "*Quellen: kjt.lu (KJT – Kanner-Jugendtelefon, e Service vun CJF Lëtzebuerg a.s.b.l.), consultéiert de 24. November 2026 op Däitsch, Englesch a Franséisch; stopline.bee-secure.lu. Fräi Iwwersetzung: de Site huet keng komplett lëtzebuergesch Versioun. Déi genau Zäiten, d'Deeg mat enger Offer op Englesch an aner Detailer, déi ännere kënnen, gi bewosst net genannt. D'Erënnerung un d'Noutruffnummer 112 ass eng Ergänzung vun de Moderatoren. Nëmmen allgemeng Informatiounen. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_cnpd{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/kjt_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 50, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
